-- 训练师问候语（npc_trainer_greeting）
--
-- 共 25 条，只写 content_loc4（简体中文）列，这些列原本全部为空。
-- 译文遵守魔兽官方术语（例：traveler -> 旅行者，seal -> 圣印）。

SET NAMES utf8mb4;

UPDATE `npc_trainer_greeting` SET `content_loc4` = '你好，法师！准备好接受训练了吗？' WHERE `content_default` = 'Hello, mage!  Ready for some training?';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '你好，牧师！准备好接受训练了吗？' WHERE `content_default` = 'Hello, priest!  Ready for some training?';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '你好，术士！准备好接受训练了吗？' WHERE `content_default` = 'Hello, warlock! Ready for some training?';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '想学学怎么把采到的矿石打造成武器和金属护甲吗？' WHERE `content_default` = 'Care to learn how to turn the ore that you find into weapons and metal armor?';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '采集草药既需要知识，也需要直觉。' WHERE `content_default` = 'Searching for herbs requires both knowledge and instinct.';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '你好，猎人！准备好接受训练了吗？' WHERE `content_default` = 'Hello, hunter!  Ready for some training?';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '你好，战士！准备好接受训练了吗？' WHERE `content_default` = 'Hello, warrior!  Ready for some training?';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '你好，盗贼！准备好接受训练了吗？' WHERE `content_default` = 'Hello, rogue!  Ready for some training?';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '你好，圣骑士！准备好接受训练了吗？' WHERE `content_default` = 'Hello, paladin!  Ready for some training?';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '你好，萨满！准备好接受训练了吗？' WHERE `content_default` = 'Hello, shaman!  Ready for some training?';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '你好！要我教你如何把捡到的布匹制成布甲吗？' WHERE `content_default` = 'Greetings!  Can I teach you how to turn found cloth into cloth armor?';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '掌握炼金术后，你就能把采到的草药制成治疗药水和其他各类药剂。' WHERE `content_default` = 'With alchemy you can turn found herbs into healing and other types of potions.';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '从猎杀的野兽身上剥取皮革，需要一双稳健的手。' WHERE `content_default` = 'It requires a steady hand to remove the leather from a slain beast.';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '附魔是一门以魔法强化现有装备的技艺。' WHERE `content_default` = 'Enchanting is the art of improving existing items through magic. ';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '要我教你如何把从野兽身上取下的肉做成美味佳肴吗？' WHERE `content_default` = 'Can I teach you how to turn the meat you find on beasts into a feast?';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '你好！要我教你如何把野兽的毛皮制成护甲吗？' WHERE `content_default` = 'Greetings!  Can I teach you how to turn beast hides into armor?';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '我可以教你如何用鱼竿钓鱼。' WHERE `content_default` = 'I can teach you how to use a fishing pole to catch fish.';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '只要掌握了基础，工程学其实非常简单。' WHERE `content_default` = 'Engineering is very simple once you grasp the basics.';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '没有深入地底挖掘过，就不算真正活过。' WHERE `content_default` = 'You have not lived until you have dug deep into the earth.';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '来，让我教你怎么包扎伤口……' WHERE `content_default` = 'Here, let me show you how to bind those wounds....';
UPDATE `npc_trainer_greeting` SET `content_loc4` = '欢迎！' WHERE `content_default` = 'Welcome!';
